iew::e(number_format((float)$item['estimated_weight_g'],2,'.','')) ?>"><?php else: ?><?= View::e(number_format((float)($item['actual_weight_g']??$item['estimated_weight_g']),2,',',' ')) ?> g<?php endif; ?></td><?php if($closed): ?><td><?= $item['weight_before_g']===null?'—':View::e(number_format((float)$item['weight_before_g'],2,',',' ').' → '.number_format((float)$item['weight_after_g'],2,',',' ').' g') ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php if(!$closed&&$canEdit): ?><div class="print-job-actions"><label><?= View::t('status') ?><select name="status"><?php foreach(['ready','printing','failed','cancelled'] as $status): ?><option value="<?= $status ?>" <?= $job['status']===$status?'selected':'' ?>><?= View::t('print_status_'.$status) ?></option><?php endforeach; ?></select></label><button class="secondary-button" formaction="<?= View::e($basePath) ?>/print-jobs/<?= View::e($job['id']) ?>"><?= View::t('save_without_deduction') ?></button><button><?= View::t('complete_and_deduct') ?></button></div></form><?php endif; ?></section>
